import React from 'react';
import styles from './MainPage.module.css';

const MainPage = () => {
  return (
    <div className={styles.page}>
      {/* Container 1: Movie List */}
      <div className={styles.sectionContainer}>
        <h1 className={styles.title}>Movie List</h1>
        <div className={styles.content}>Movie List Content</div>
      </div>

      {/* Container 2: Metadata Editor */}
      <div className={styles.sectionContainer}>
        <h2 className={styles.subtitle}>Metadata Editor</h2>
        <form className={styles.form}>
          <div>Metadata Form</div>
          <ul className={styles.list}>
            <li>Actors</li>
            <li>Categories</li>
          </ul>
        </form>
      </div>

      {/* Category Selector (standalone) */}
      <div className={styles.selector}>Category Selector</div>
    </div>
  );
};

export default MainPage;
